// APPT 21 "Parse detail" — runs after the tls-fetch HTTP call.
// Inputs: $json = tls-fetch response {status, final_url, body} (or an error object if the
// fetch failed under onError:continueRegularOutput). Base listing = the workflow input item.
const base = $('In').item.json;
const resp = $json || {};
const html = typeof resp.body === 'string' ? resp.body : '';

// default: return the listing unchanged (fetch failed / nothing parsed)
function passthrough(reason) {
  return [{ json: { ...base, _enriched: false, _enrich_note: reason || null } }];
}
if (!html || (resp.status && resp.status >= 400)) {
  return passthrough('fetch ' + (resp.status || 'failed'));
}

// Comparis detail: extract __NEXT_DATA__ JSON
if ((base.source || '').startsWith('email-comparis') || /comparis\.ch/.test(resp.final_url || '')) {
  const m = html.match(/__NEXT_DATA__"\s+type="application\/json">([\s\S]*?)<\/script>/);
  if (!m) return passthrough('no __NEXT_DATA__');
  let pp;
  try { pp = JSON.parse(m[1]).props.pageProps; } catch (e) { return passthrough('json parse failed'); }
  const ad = pp.ad || {};
  const vendor = (pp.contactInformation && pp.contactInformation.VendorInformation) || {};

  const money = v => { if (v == null) return null; const s = String(v).match(/([\d']+)/); return s ? parseInt(s[1].replace(/'/g, ''), 10) : null; };
  const priceByKey = k => { const p = (ad.PriceInformation || []).find(x => x.Key === k); return p ? money(p.Value) : null; };
  const featureOn = keys => (ad.Features || []).some(f => f.Value && keys.includes(f.Key));

  const net = priceByKey('NetRent');
  const gross = priceByKey('GrossRent') ?? money(ad.PriceText);
  let charges = priceByKey('Charges') ?? priceByKey('AdditionalCosts');
  if (charges == null && net != null && gross != null && gross > net) charges = gross - net;
  const addr = ad.AddressSegments || {};
  const address_raw = [addr.Street, addr.StreetNumber].filter(Boolean).join(' ') || base.address_raw;
  const lat = ad.MapData && typeof ad.MapData.GeoPosLat === 'number' ? ad.MapData.GeoPosLat : null;
  const lng = ad.MapData && typeof ad.MapData.GeoPosLng === 'number' ? ad.MapData.GeoPosLng : null;
  const features = {
    balcony: featureOn(['HasBalconies', 'HasTerrace']),
    elevator: featureOn(['HasLift']),
    parking: featureOn(['HasParkingIndoor', 'HasParkingOutdoor', 'HasParking']),
    dishwasher: featureOn(['HasDishwasher']),
    washingMachine: featureOn(['HasWashingMachine']),
    pets: featureOn(['PetsAllowed']),
    minergie: featureOn(['MinergieCertified', 'MinergieCertified_Label']),
    wheelchair: featureOn(['WheelchairAccessible']),
  };
  const images = Array.isArray(ad.ImageUrls) ? ad.ImageUrls.slice(0, 5) : base.images;
  const agency = vendor.Name || null;
  const agency_contact = [vendor.VendorContact, vendor.Phone].filter(Boolean).join(' · ') || null;

  return [{ json: {
    ...base,
    _enriched: true,
    _enrich_note: null,
    url: ad.SharingUrl || base.url,
    rent_net: net ?? base.rent_net,
    rent_gross: gross ?? base.rent_gross,
    charges: charges ?? base.charges,
    m2: (ad.Area ?? ad.LivingSpace) ? Number(ad.Area ?? ad.LivingSpace) : base.m2,
    rooms: ad.NumRooms != null ? Number(ad.NumRooms) : base.rooms,
    commune: addr.City || base.commune,
    address_raw,
    floor: ad.Floor != null ? String(ad.Floor) : base.floor,
    year_built: ad.ConstructionYear ?? base.year_built,
    description: (ad.Remarks && ad.Remarks.length > (base.description || '').length) ? ad.Remarks : base.description,
    images,
    features,
    lat, lng,
    agency,
    agency_contact,
    partner: ad.PartnerName || null,
  } }];
}

return passthrough('source not enrichable yet');

const listing = $('Parse detail').item.json;
const row = ($json && $json.reputation) ? $json : null;
let agency_reputation = null;
if (row) agency_reputation = row.reputation + (row.note ? ' — ' + row.note : '');
return [{ json: { ...listing, agency_reputation } }];

// APPT 21 "SMG parse" — enrich an SMG-pool listing (immoscout24 / homegate: same
// Vue/Pinia frontend, window.__PINIA_INITIAL_STATE__.listing.listing) from its detail
// page, fetched through tls-fetch WITH the replayed DataDome cookie. Also classifies
// the result for the circuit breaker (see portal_cookies / tls-fetch README):
//   200 → enrich + roll the token forward (_dd_new_status='active', _dd_refreshed=new)
//   403 → cookie dead → _dd_blocked=true, _dd_new_status='expired' (NEVER retried; the
//         breaker then stops all fetches for that portal until the user re-seeds it)
//   other (timeout/5xx) → transient: leave token active, listing un-enriched, no alert.
const base = $('SMG portal?').item.json;
const portal = (base.source || '').replace('email-', '');
const resp = $json || {};
const status = Number(resp.status) || 0;
const html = typeof resp.body === 'string' ? resp.body : '';

function out(extra) {
  return [{ json: { ...base, _enriched: false, _portal: portal, _dd_status: status,
    _dd_blocked: status === 403,
    _dd_new_status: status === 403 ? 'expired' : 'active',
    _dd_refreshed: '',
    ...extra } }];
}
if (status !== 200 || !html) return out({ _enrich_note: 'fetch ' + (status || 'failed') });

// live listing data lives in window.__PINIA_INITIAL_STATE__ (Vue/Pinia; note spaces around =)
const m = html.match(/window\.__PINIA_INITIAL_STATE__\s*=\s*(\{[\s\S]*?\})\s*<\/script>/);
if (!m) return out({ _enrich_note: 'no pinia state' });
let L;
try { L = JSON.parse(m[1]).listing.listing; } catch (e) { return out({ _enrich_note: 'pinia parse failed' }); }
if (!L) return out({ _enrich_note: 'no listing object' });

const ch = L.characteristics || {};
const addr = L.address || {};
const geo = addr.geoCoordinates || {};
const rent = (L.prices && L.prices.rent) || {};

// localization: prefer fr, then de/it/en
const loc = L.localization || {};
const lang = ['fr', 'de', 'it', 'en'].find(k => loc[k] && loc[k].text) || Object.keys(loc)[0];
const txt = (loc[lang] && loc[lang].text) || {};
const stripHtml = s => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/[ \t]+\n/g, '\n').trim();
const title = txt.title || base.title;
const description = stripHtml(txt.description) || base.description;

// images: localization.<lang>.attachments[] type IMAGE
const atts = (loc[lang] && Array.isArray(loc[lang].attachments)) ? loc[lang].attachments : [];
const images = atts.filter(a => a && a.type === 'IMAGE' && a.url).map(a => a.url).slice(0, 6);

// rent: prices.rent.{net,gross,extra} are plain numbers on this platform (occasionally
// wrapped as {amount}); fall back to a currency-anchored parse of the description text.
const money = v => { if (v == null) return null; const s = String(v).match(/(\d[\d'\u2019 ]*)/); return s ? parseInt(s[1].replace(/['\u2019 ]/g, ''), 10) : null; };
const amtOf = v => (v && typeof v === 'object') ? money(v.amount) : money(v);
let net = amtOf(rent.net);
let gross = amtOf(rent.gross);
let charges = amtOf(rent.extra);
if (net == null && gross == null && description) {
  // require an explicit currency marker (CHF / .- / fr) so a bare year like 2026
  // in an availability date is not misread as the rent.
  const mm = description.match(/chf\s*(\d[\d'\u2019 ]{2,})|(\d[\d'\u2019 ]{2,})\s*(?:\.-|chf|frs?\b)/i);
  const amt = mm ? parseInt((mm[1] || mm[2]).replace(/['\u2019 ]/g, ''), 10) : null;
  if (amt && amt > 200 && amt < 20000) {
    if (/charges?\s*comprises?|inkl|incl|c\.?c\.?/i.test(description)) gross = amt; else net = amt;
  }
}
if (charges == null && net != null && gross != null && gross > net) charges = gross - net;

const lister = L.lister || {};
const agency = lister.legalName || (L.listerBranding && L.listerBranding.legalName) || null;
const phone = lister.contacts && lister.contacts.inquiry && lister.contacts.inquiry.phone;
const street = (addr.street && addr.street !== addr.locality) ? addr.street : base.address_raw;

return [{ json: {
  ...base,
  _enriched: true,
  _enrich_note: null,
  _portal: portal,
  _dd_status: 200,
  _dd_blocked: false,
  _dd_new_status: 'active',
  _dd_refreshed: resp.datadome || '',
  title,
  rent_net: net ?? base.rent_net,
  rent_gross: gross ?? base.rent_gross,
  charges: charges ?? base.charges,
  rooms: ch.numberOfRooms != null ? Number(ch.numberOfRooms) : base.rooms,
  m2: ch.livingSpace != null ? Number(ch.livingSpace) : base.m2,
  commune: addr.locality || base.commune,
  address_raw: street,
  description,
  images: images.length ? images : base.images,
  lat: typeof geo.latitude === 'number' ? geo.latitude : null,
  lng: typeof geo.longitude === 'number' ? geo.longitude : null,
  agency,
  agency_contact: phone || null,
} }];

const listing = $('SMG parse').item.json;
const row = ($json && $json.reputation) ? $json : null;
let agency_reputation = null;
if (row) agency_reputation = row.reputation + (row.note ? ' — ' + row.note : '');
// strip the internal circuit-breaker fields before emitting downstream
const { _dd_status, _dd_blocked, _dd_new_status, _dd_refreshed, _portal, ...clean } = listing;
return [{ json: { ...clean, agency_reputation } }];

// cookie inactive/expired → circuit breaker OPEN: make no request, pass the
// email-sourced listing through un-enriched so it is still notified.
return [{ json: { ...$('SMG portal?').item.json, _enriched: false, _enrich_note: 'SMG cookie inactive' } }];

// The parent Execute-Workflow node receives the LAST executed node's data, and on
// the blocked path that was the ntfy response — which then poisoned APPT 20's
// triage/scoring (2026-07-19: Peer baseline died on the ntfy message id). Hand the
// un-enriched listing back (internal _dd_*/_portal fields stripped) so APPT 20's
// 'Enrich held?' gate parks it as pending_enrich instead of notifying it.
const { _dd_status, _dd_blocked, _dd_new_status, _dd_refreshed, _portal, ...clean } = $('SMG parse').item.json;
return [{ json: { ...clean, _enrich_note: 'SMG cookie expired (403)' } }];
